import parse from '@hey-bible/bible-reference-parser';

export function parseBibleReference(query: string) {
  const parsed = parse(query);

  if (!parsed) {
    return null;
  }

  return {
    ...parsed,
    chapter: Number(parsed.chapter),
  } as NormalizedBibleParserResult;
}

export type NormalizedBibleParserResult = {
  book: string;
  chapter: number;
  verses: number[] | 'ALL';
};
